insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_health2_v1'
from (values
('115.39.c.3',3,'A student wrote down three strengths and two skills to improve, then picked one to work on this month. This builds a healthy self-concept through what?','["Self-assessment and goal setting", "Ignoring weaknesses", "Avoiding feedback", "Comparing to others"]'::jsonb,0,'Honest self-evaluation plus a goal builds self-concept.','original'),
('115.39.c.3',3,'Which decision-making step comes right after listing the possible choices?','["Acting without thinking", "Weighing the possible outcomes of each choice", "Asking nobody", "Choosing at random"]'::jsonb,1,'Decision making means comparing consequences.','original'),
('115.39.c.4',3,'Chronic bullying is a risk factor for mental health problems because it can lead to what?','["Better resilience for everyone", "No effect", "Ongoing stress, anxiety or depression", "Higher confidence"]'::jsonb,2,'Risk factors increase the chance of mental health problems.','original'),
('115.39.c.4',3,'Which is a protective factor that helps a student cope with stress?','["Avoiding all help", "Staying isolated", "Skipping meals", "Having a caring mentor and a regular sleep routine"]'::jsonb,3,'Protective factors build resilience.','original'),
('115.39.c.6',2,'A person eating about 2,000 calories a day who wants to follow MyPlate guidance should fill about half of the plate with what?','["Fruits and vegetables", "Candy", "Fried food", "Soda"]'::jsonb,0,'MyPlate recommends half the plate from fruits and vegetables.','original'),
('115.39.c.6',3,'Nutrition recommendations for teens suggest limiting what?','["Vegetables", "Sugary drinks and foods high in saturated fat and sodium", "Whole grains", "Water"]'::jsonb,1,'Limit added sugar, saturated fat and sodium.','original'),
('115.39.c.10',2,'A student who finds a fire alarm sounding in the building should first do what?','["Wait at a desk", "Hide in a restroom", "Leave by the planned route and report to the meeting spot", "Go back for belongings"]'::jsonb,2,'Follow the evacuation plan.','original'),
('115.39.c.10',2,'CPR for an adult in cardiac arrest involves chest compressions at a depth of about what?','["No pressing at all", "8 inches", "Half an inch", "2 inches at a steady rapid rate"]'::jsonb,3,'Compressions must be deep enough to circulate blood.','original'),
('115.39.c.15',3,'Long-term heavy alcohol use is associated with damage to which organ?','["The liver", "The toenails", "The hair", "The earlobes"]'::jsonb,0,'Alcohol is processed by the liver.','original'),
('115.39.c.15',3,'Which short-term effect is associated with marijuana use?','["Better focus on driving", "Impaired memory, judgment and coordination", "Stronger balance", "Improved reaction time"]'::jsonb,1,'It affects thinking and motor skills.','original'),
('115.39.c.16',3,'Which is a treatment approach for substance use disorders?','["Hiding the problem", "Punishing only", "Behavioral therapy combined with medical support", "Waiting it out"]'::jsonb,2,'Evidence-based treatment combines approaches.','original'),
('115.39.c.16',3,'A person who is addicted may need treatment because addiction is what?','["Always harmless", "A phase", "Only a weakness", "A medical condition that is treatable"]'::jsonb,3,'Treatment can lead to recovery.','original'),
('115.39.c.18',3,'Prevention of substance abuse is most effective when it includes what?','["Education, strong family involvement and positive peer groups", "Silence", "Easy access", "Fear alone"]'::jsonb,0,'Prevention programs use many supports.','original'),
('115.39.c.18',3,'Which message is an example of an effective prevention strategy at school?','["Hiding information", "Teaching refusal skills and offering alternative activities", "Punishing only", "Ignoring drug use"]'::jsonb,1,'Skills and alternatives lower use.','original'),
('115.39.c.1.A',3,'Which factor most limits a teen''s access to health care?','["Free clinics", "Telehealth", "Lack of insurance or transportation", "Having a doctor nearby"]'::jsonb,2,'Cost and access are common barriers.','original'),
('115.39.c.1.A',3,'A community health clinic often helps people who cannot afford care by doing what?','["Charging the most", "Refusing all patients", "Closing early", "Charging fees based on income"]'::jsonb,3,'Sliding-scale fees increase access.','original'),
('115.39.c.1.B',3,'One way to overcome a language barrier at a doctor''s visit is to use what?','["A qualified interpreter", "A guess", "A rumor", "Silence"]'::jsonb,0,'Interpreters help patients understand.','original'),
('115.39.c.1.B',3,'A teen with no transportation to a clinic could overcome this barrier by doing what?','["Ignoring symptoms", "Using a telehealth visit or school-based health service", "Waiting months", "Skipping care"]'::jsonb,1,'Alternatives improve access.','original'),
('115.39.c.1.C',3,'A law requiring immunizations before school enrollment is an example of a policy that does what?','["Prevents learning", "Raises disease rates", "Protects community health", "Lowers school safety"]'::jsonb,2,'Public health laws reduce disease spread.','original'),
('115.39.c.1.C',3,'Anti-discrimination laws influence health by doing what?','["Limiting treatment", "Ending insurance", "Raising costs", "Helping ensure equal access to care"]'::jsonb,3,'Policies shape access.','original'),
('115.39.c.2.A',3,'A relationship in which one person isolates the other from friends has what effect?','["Negative effects on emotional and social health", "No effects", "Positive effects only", "Better health"]'::jsonb,0,'Control and isolation are harmful.','original'),
('115.39.c.2.A',3,'A supportive friendship tends to improve physical health because it does what?','["Ends exercise", "Reduces stress and encourages healthy habits", "Increases risk", "Limits sleep"]'::jsonb,1,'Support helps health.','original'),
('115.39.c.2.B',3,'Which communication behavior shows consideration for others'' differences?','["Speaking over them", "Mocking accents", "Listening without interrupting and asking respectful questions", "Ignoring them"]'::jsonb,2,'Respectful communication values differences.','original'),
('115.39.c.2.B',3,'Using "I" statements helps because they do what?','["Attack the listener", "End the talk", "Hide feelings", "Express your feelings without blaming"]'::jsonb,3,'They reduce defensiveness.','original'),
('115.39.c.2.C',3,'Two students disagree about a group project. Which technique is most effective for resolving the conflict?','["Listening to both sides and finding a compromise", "Threatening", "Ignoring it", "Walking away angry"]'::jsonb,0,'Compromise resolves conflicts.','original'),
('115.39.c.2.C',3,'Mediation is effective in conflict resolution because it does what?','["Blames one side", "Uses a neutral third person to help both sides reach an agreement", "Ends communication", "Picks a winner by force"]'::jsonb,1,'A mediator guides the discussion.','original'),
('115.39.c.5.A',3,'Positive stress, such as preparing for a performance, can build resilience by doing what?','["Causing harm", "Reducing effort", "Teaching coping skills and confidence", "Ending motivation"]'::jsonb,2,'Manageable stress can help growth.','original'),
('115.39.c.5.A',3,'A challenge that is difficult but manageable is an example of what?','["Toxic stress", "No stress", "Harmful abuse", "Positive stress"]'::jsonb,3,'It builds resilience.','original'),
('115.39.c.5.B',3,'Which is a healthy way to manage stress?','["Exercise, sleep, talking to someone and deep breathing", "Using alcohol", "Avoiding all people", "Skipping sleep"]'::jsonb,0,'Healthy coping lowers stress.','original'),
('115.39.c.5.B',3,'Seeking counseling for anxiety is a healthy choice because it does what?','["Hides it", "Provides tools and support for managing symptoms", "Is a sign of failure", "Worsens it"]'::jsonb,1,'Counseling is effective.','original'),
('115.39.c.5.C',3,'A health-risk behavior associated with eating disorders is what?','["Eating with friends", "Balanced meals", "Extreme dieting and a distorted view of body image", "Regular exercise only"]'::jsonb,2,'Eating disorders are serious illnesses.','original'),
('115.39.c.5.C',3,'A person showing signs of an eating disorder should be encouraged to do what?','["Ignore it", "Hide it", "Diet harder", "See a doctor or counselor trained in treating eating disorders"]'::jsonb,3,'Professional treatment helps recovery.','original'),
('115.39.c.5.D',3,'Why is it helpful to know about the 988 Suicide and Crisis Lifeline?','["It gives free, confidential help any time to someone in distress", "It costs money", "It is only for adults", "It replaces family"]'::jsonb,0,'Knowing resources helps people reach support.','original'),
('115.39.c.5.D',3,'If a friend seems to be in crisis, calling or texting 988 can help by doing what?','["Delaying help", "Connecting you to trained counselors for guidance and support", "Starting an argument", "Hiding the issue"]'::jsonb,1,'Counselors can guide next steps.','original'),
('115.39.c.5.E',3,'Looking at local, state and national suicide data helps communities by doing what?','["Increasing risk", "Hiding the issue", "Showing where prevention resources are needed", "Ending prevention"]'::jsonb,2,'Data guides prevention planning.','original'),
('115.39.c.5.E',3,'Which source provides national data on suicide rates?','["A rumor", "A guess", "A social media post", "The Centers for Disease Control and Prevention"]'::jsonb,3,'The CDC publishes national health data.','original'),
('115.39.c.7.A',3,'Compared with a sedentary lifestyle, an active lifestyle lowers the risk of what?','["Heart disease and type 2 diabetes", "Strong bones", "Better sleep", "Higher energy"]'::jsonb,0,'Activity reduces chronic disease risk.','original'),
('115.39.c.7.A',3,'Adults and teens are generally advised to get about how much physical activity?','["10 minutes a week", "At least 60 minutes a day for teens", "5 minutes a month", "None"]'::jsonb,1,'Teens need about 60 minutes daily.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Health Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
